MERGE INTO RAWDATA.PROVIDER_NETWORK_CROSSWALK AS TGT
USING (SELECT PNCKEY,CLIENTID,TPAID,TPADIVID,WEBDIRECTORYVISIBLEIND,CARETYPENAME,COVERAGETYPE,PLANNAME,PROVDIRH2PRODUCTKEY,PROVDIRH2SUBPRODUCTKEY,H2ENTITYNAME,PROVDIRH2PRODUCTNAME,PROVDIRH2SUBPRODUCTNAME,PRODUCTNAME,PRODUCTTYPENAME,ALTDESTINATIONURL,ALTERNATENETWORKNAME,SUPERPCPRECORDSFLAG,LEVELEDSUBPRODUCTIND,MARKETIDENTITYNAME,CONTRACTMODELNAME,SOURCENAME,MC400IPACODE,MC400PLANTYPECODE,OUTOFAREAMESSAGETEMPLATE,COVERAGEVALUE,LASTUPDATEDDATETIME,LASTUPDATEDUSERNAME,PROVDIRNETWORKID,DNVPLANTYPECODE,RIDERTYPECODE,PLANNAMEDISPLAYKEY,COVERAGETYPEDISPLAYORDERNBR,PLANNAMEDISPLAYORDERNBR,LINEOFBUSINESSNAME,SPECIALTYLISTIND,YEARSPECIFICPLANIND,PLANYEAR,UPMCOWNEDDISPLAYIND,CHANGENOTIFICATIONTEXT,INCLUDEINDIRECTORY,FORMULARYCODE
	FROM RAWDATA.temp_PROVIDER_NETWORK_CROSSWALK
	MINUS 
	SELECT PNCKEY,CLIENTID,TPAID,TPADIVID,WEBDIRECTORYVISIBLEIND,CARETYPENAME,COVERAGETYPE,PLANNAME,PROVDIRH2PRODUCTKEY,PROVDIRH2SUBPRODUCTKEY,H2ENTITYNAME,PROVDIRH2PRODUCTNAME,PROVDIRH2SUBPRODUCTNAME,PRODUCTNAME,PRODUCTTYPENAME,ALTDESTINATIONURL,ALTERNATENETWORKNAME,SUPERPCPRECORDSFLAG,LEVELEDSUBPRODUCTIND,MARKETIDENTITYNAME,CONTRACTMODELNAME,SOURCENAME,MC400IPACODE,MC400PLANTYPECODE,OUTOFAREAMESSAGETEMPLATE,COVERAGEVALUE,LASTUPDATEDDATETIME,LASTUPDATEDUSERNAME,PROVDIRNETWORKID,DNVPLANTYPECODE,RIDERTYPECODE,PLANNAMEDISPLAYKEY,COVERAGETYPEDISPLAYORDERNBR,PLANNAMEDISPLAYORDERNBR,LINEOFBUSINESSNAME,SPECIALTYLISTIND,YEARSPECIFICPLANIND,PLANYEAR,UPMCOWNEDDISPLAYIND,CHANGENOTIFICATIONTEXT,INCLUDEINDIRECTORY,FORMULARYCODE
	FROM RAWDATA.PROVIDER_NETWORK_CROSSWALK
	) AS SRC

ON (TGT.PNCKEY = SRC.PNCKEY)

WHEN MATCHED 
THEN UPDATE
	SET 
	TGT.LASTUPDATEDDATETIME = CURRENT_TIMESTAMP()
WHEN NOT MATCHED 
THEN INSERT
	(
		PNCKEY,CLIENTID,TPAID,TPADIVID,WEBDIRECTORYVISIBLEIND,CARETYPENAME,COVERAGETYPE,PLANNAME,PROVDIRH2PRODUCTKEY,PROVDIRH2SUBPRODUCTKEY,H2ENTITYNAME,PROVDIRH2PRODUCTNAME,PROVDIRH2SUBPRODUCTNAME,PRODUCTNAME,PRODUCTTYPENAME,ALTDESTINATIONURL,ALTERNATENETWORKNAME,SUPERPCPRECORDSFLAG,LEVELEDSUBPRODUCTIND,MARKETIDENTITYNAME,CONTRACTMODELNAME,SOURCENAME,MC400IPACODE,MC400PLANTYPECODE,OUTOFAREAMESSAGETEMPLATE,COVERAGEVALUE,LASTUPDATEDDATETIME,LASTUPDATEDUSERNAME,PROVDIRNETWORKID,DNVPLANTYPECODE,RIDERTYPECODE,PLANNAMEDISPLAYKEY,COVERAGETYPEDISPLAYORDERNBR,PLANNAMEDISPLAYORDERNBR,LINEOFBUSINESSNAME,SPECIALTYLISTIND,YEARSPECIFICPLANIND,PLANYEAR,UPMCOWNEDDISPLAYIND,CHANGENOTIFICATIONTEXT,INCLUDEINDIRECTORY,FORMULARYCODE
	)
VALUES
	(
		SRC.PNCKEY,SRC.CLIENTID,SRC.TPAID,SRC.TPADIVID,SRC.WEBDIRECTORYVISIBLEIND,SRC.CARETYPENAME,SRC.COVERAGETYPE,SRC.PLANNAME,SRC.PROVDIRH2PRODUCTKEY,SRC.PROVDIRH2SUBPRODUCTKEY,SRC.H2ENTITYNAME,SRC.PROVDIRH2PRODUCTNAME,SRC.PROVDIRH2SUBPRODUCTNAME,SRC.PRODUCTNAME,SRC.PRODUCTTYPENAME,SRC.ALTDESTINATIONURL,SRC.ALTERNATENETWORKNAME,SRC.SUPERPCPRECORDSFLAG,SRC.LEVELEDSUBPRODUCTIND,SRC.MARKETIDENTITYNAME,SRC.CONTRACTMODELNAME,SRC.SOURCENAME,SRC.MC400IPACODE,SRC.MC400PLANTYPECODE,SRC.OUTOFAREAMESSAGETEMPLATE,SRC.COVERAGEVALUE,CURRENT_TIMESTAMP(),SRC.LASTUPDATEDUSERNAME,SRC.PROVDIRNETWORKID,SRC.DNVPLANTYPECODE,SRC.RIDERTYPECODE,SRC.PLANNAMEDISPLAYKEY,SRC.COVERAGETYPEDISPLAYORDERNBR,SRC.PLANNAMEDISPLAYORDERNBR,SRC.LINEOFBUSINESSNAME,SRC.SPECIALTYLISTIND,SRC.YEARSPECIFICPLANIND,SRC.PLANYEAR,SRC.UPMCOWNEDDISPLAYIND,SRC.CHANGENOTIFICATIONTEXT,SRC.INCLUDEINDIRECTORY,SRC.FORMULARYCODE
	)
;
	
--Flip the minus and delete from the target
DELETE FROM RAWDATA.PROVIDER_NETWORK_CROSSWALK TGT
USING
(SELECT PNCKEY
	FROM RAWDATA.PROVIDER_NETWORK_CROSSWALK
	MINUS 
	SELECT PNCKEY
	FROM RAWDATA.temp_PROVIDER_NETWORK_CROSSWALK
	) SRC
WHERE TGT.PNCKEY = SRC.PNCKEY
;

SELECT 'Finished updating static data table RAWDATA.PROVIDER_NETWORK_CROSSWALK';
